public class Main {
    public static void main(String[] args) {
        String word = "Java"; //~ Four characters: J at index 0, a at 1, v at 2, a at 3.
        String upper = word.toUpperCase(); //~ Strings never change. toUpperCase() makes a NEW string, "JAVA".
        char first = word.charAt(0); //~ charAt(0) is the first character: 'J'.
        System.out.println(first + " " + upper + " " + word.length()); //~ length() counts the characters: 4.
    }
}

